public class AutofillDetector extends ResourceXmlDetector {
    private static final String AUTO_FILL_HINTS = "autofillHints";
    private static final String IMPORTANT_FOR_AUTO_FILL = "importantForAutofill";
    private static final int AUTOFILL_TARGET_SDK = 26;
    private static final Set<String> AUTO_FILLABLE_WIDGETS = Sets.newHashSet(
            "AutoCompleteTextView",
            "EditText",
            "MultiAutoCompleteTextView",
            "TextInputEditText"
    );
    @Override
    public Collection<String> getApplicableElements() { return AUTO_FILLABLE_WIDGETS; }
    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (getTargetSdk(context) < AUTOFILL_TARGET_SDK) return;
        if (element.hasAttribute(AUTO_FILL_HINTS)) return;
        if (isUnimportantForAutofill(element)) return;
        context.report(ISSUE, element, context.getLocation(element), "...");
    }
    private boolean isUnimportantForAutofill(Element element) {
        while (element != null) {
            if (element.hasAttribute(IMPORTANT_FOR_AUTO_FILL)) {
                String value = element.getAttribute(IMPORTANT_FOR_AUTO_FILL);
                if (value.equals("no") || value.equals("noExcludeDescendants")) return true;
            }
            Node parent = element.getParentNode();
            if (parent == null || parent.getNodeType() != Node.ELEMENT_NODE) break;
            element = (Element) parent;
        }
        return false;
    }
    private static int getTargetSdk(XmlContext context) {
        return context.getProject().getBuildSdk();
    }
}
